## Short answer

Never let the math parser and the math *evaluator* be the same component. "Validate then evaluate" only works if the validator is a strict **allowlist over a parsed tree** — not a regex denylist, and not `eval()` with `{"__builtins__": {}}` (that sandbox is trivially escapable via `().__class__.__bases__[0].__subclasses__()`).

I ran the validation + evaluation tools against candidate payloads to show the behavior you want, then generated an OWASP-aligned hardening prompt for your codebase.

---

## 1. What the tools actually showed

| Payload | Result | Why it matters |
|---|---|---|
| `(a + b) * 2 - sqrt(16) / 4` with `a=10, b=5` | **valid → `29`** | Legit input round-trips |
| `(a + b) * 2 - sqrt(16) / 4` before `a`,`b` were defined | **`Undefined variable: a`** | ✅ Names are resolved *only* from an explicit symbol table — never from the ambient namespace |
| `__import__("os").system("cat /etc/passwd")` | **rejected** — `Unexpected character '_'` | ✅ Grammar has no identifier/attribute/call surface |
| `().__class__.__bases__[0].__subclasses__()` | **rejected** | ✅ Attribute traversal is syntactically impossible |
| `(1 + 2` | **rejected** — `Expected ')' after expression` | ✅ Balance check works |
| `2 ** 10` | **rejected**; `2 ^ 10` → `1024` | ⚠️ The grammar uses `^` for power, and **`**` is not a token** — so the classic `9**9**9**9` bomb never parses |
| `2 ^ 2 ^ 2 ^ 2` | `65536` | ✅ Right-associative, bounded |
| `10 ^ 100` | `1e+100` | ⚠️ **Silent int→float coercion** — precision loss with no warning |
| `10 ^ 1000` | **`null`** | 🚩 **Fail-open / error masking** — a magnitude guard returns `null` instead of raising |
| `2 ^ 2 ^ 2 ^ 2 ^ 2` | **`null`** | 🚩 Same silent cap |
| `a / (b - 5)` (divide by zero) | **`null`** | 🚩 Division by zero swallowed |
| `sqrt(-1)` | **`null`** | 🚩 Domain error swallowed |
| `max_depth=3` on `((((((((((1+2))))))))))` | **valid** | 🚩 The depth limit did **not** fire — do not rely on a single depth knob |
| `batch_evaluate` | **tool error** | 🚩 Misconfigured execution path failed without a fallback — exactly what "fail closed" prevents |

**Three lessons from that run:** (a) allowlist grammars do kill the obvious RCE vectors; (b) exponentiation is still a live DoS vector via `^`, not `**`; (c) returning `null` for "too big / divide-by-zero / domain error" is *the* anti-pattern — the caller cannot distinguish `0` from `rejected`, so auth and business logic downstream make decisions on garbage.

---

## 2. Reference implementation

```python
# safe_math.py
import ast, math, operator
from dataclasses import dataclass

MAX_LEN       = 512      # characters
MAX_DEPTH     = 20       # AST nesting
MAX_NODES     = 128      # total AST nodes
MAX_BITS      = 4096     # hard cap on integer magnitude
MAX_EXPONENT  = 64       # cap on |exponent|
MAX_STEPS     = 10_000   # evaluation budget

class ExprRejected(Exception):
    """Internal: carries detail; never surface `detail` to users."""
    def __init__(self, code: str, detail: str = ""):
        self.code, self.detail = code, detail
        super().__init__(f"{code}: {detail}")

_BINOPS = {ast.Add: operator.add, ast.Sub: operator.sub,
           ast.Mult: operator.mul, ast.Div: operator.truediv,
           ast.FloorDiv: operator.floordiv, ast.Mod: operator.mod,
           ast.Pow: operator.pow}
_UNARY  = {ast.UAdd: operator.pos, ast.USub: operator.neg}
_FUNCS  = {"sqrt": math.sqrt, "abs": abs, "exp": math.exp, "log": math.log,
           "sin": math.sin, "cos": math.cos, "tan": math.tan,
           "floor": math.floor, "ceil": math.ceil, "min": min, "max": max}
_CONSTS = {"pi": math.pi, "e": math.e}

def _check_shape(tree: ast.Expression) -> None:
    depth = nodes = 0
    stack = [(tree, 0)]
    while stack:
        node, d = stack.pop()
        nodes += 1
        depth = max(depth, d)
        if nodes > MAX_NODES:  raise ExprRejected("TOO_COMPLEX", "node cap")
        if depth  > MAX_DEPTH: raise ExprRejected("TOO_DEEP",   "depth cap")
        stack.extend((c, d + 1) for c in ast.iter_child_nodes(node))

class _Validator(ast.NodeVisitor):
    """Default-deny: any node type not explicitly handled is rejected."""
    def generic_visit(self, node):
        raise ExprRejected("DISALLOWED_SYNTAX", type(node).__name__)

    def visit_Expression(self, node):  self.visit(node.body)
    def visit_BinOp(self, node):
        if type(node.op) not in _BINOPS:
            raise ExprRejected("DISALLOWED_OP", type(node.op).__name__)
        self.visit(node.left); self.visit(node.right)
    def visit_UnaryOp(self, node):
        if type(node.op) not in _UNARY:
            raise ExprRejected("DISALLOWED_OP", type(node.op).__name__)
        self.visit(node.operand)
    def visit_Call(self, node):
        if not isinstance(node.func, ast.Name) or node.func.id not in _FUNCS:
            raise ExprRejected("DISALLOWED_CALL", "non-allowlisted function")
        if node.keywords:
            raise ExprRejected("DISALLOWED_CALL", "kwargs not permitted")
        for arg in node.args: self.visit(arg)
    def visit_Name(self, node):
        if node.id not in _FUNCS and node.id not in _CONSTS:
            raise ExprRejected("UNKNOWN_NAME", node.id)
    def visit_Constant(self, node):
        if isinstance(node.value, bool) or not isinstance(node.value, (int, float)):
            raise ExprRejected("DISALLOWED_LITERAL", type(node.value).__name__)
        if isinstance(node.value, int) and node.value.bit_length() > MAX_BITS:
            raise ExprRejected("LITERAL_TOO_LARGE", "")
    # ast.Attribute / Subscript / Lambda / Comprehension / Import /
    # JoinedStr / Dict / List ... all fall through to generic_visit -> reject

@dataclass
class _Budget:
    steps: int

def _protected_pow(base, exp):
    if isinstance(exp, float) and not exp.is_integer():
        if abs(base) > 1e6:
            raise ExprRejected("EXPONENT_TOO_LARGE", "rational exponent")
        return base ** exp
    exp = int(exp)
    if abs(exp) > MAX_EXPONENT:
        raise ExprRejected("EXPONENT_TOO_LARGE", str(exp))
    if isinstance(base, int) and base.bit_length() * max(abs(exp), 1) > MAX_BITS:
        raise ExprRejected("RESULT_TOO_LARGE", "")
    return base ** exp

def _eval(node, b: _Budget, env: dict):
    b.steps -= 1
    if b.steps < 0:
        raise ExprRejected("BUDGET_EXCEEDED", "")
    if isinstance(node, ast.Expression): return _eval(node.body, b, env)
    if isinstance(node, ast.Constant):   return node.value
    if isinstance(node, ast.Name):
        return env[node.id] if node.id in env else _CONSTS[node.id]
    if isinstance(node, ast.UnaryOp):
        return _UNARY[type(node.op)](_eval(node.operand, b, env))
    if isinstance(node, ast.BinOp):
        left = _eval(node.left, b, env)
        right = _eval(node.right, b, env)
        if isinstance(node.op, ast.Pow):
            return _protected_pow(left, right)
        if isinstance(node.op, (ast.Div, ast.FloorDiv, ast.Mod)) and right == 0:
            raise ExprRejected("DIVIDE_BY_ZERO", "")
        return _BINOPS[type(node.op)](left, right)
    if isinstance(node, ast.Call):
        name = node.func.id
        args = [_eval(a, b, env) for a in node.args]
        try:
            return _FUNCS[name](*args)
        except (ValueError, OverflowError) as exc:
            raise ExprRejected("DOMAIN_ERROR", type(exc).__name__) from exc
    raise ExprRejected("DISALLOWED_SYNTAX", type(node).__name__)

def safe_evaluate(expression: str, variables: dict | None = None) -> float | int:
    """Validate-then-evaluate. Raises ExprRejected; never returns None."""
    if not isinstance(expression, str):
        raise ExprRejected("BAD_TYPE", type(expression).__name__)
    if not 0 < len(expression) <= MAX_LEN:
        raise ExprRejected("BAD_LENGTH", str(len(expression)))

    try:
        tree = ast.parse(expression, mode="eval")   # parse only — no compile, no eval
    except (SyntaxError, ValueError) as exc:
        raise ExprRejected("SYNTAX_ERROR", str(exc)) from exc

    _check_shape(tree)
    _Validator().visit(tree)

    env = {k: v for k, v in (variables or {}).items()
           if k in _CONSTS or k in _FUNCS or isinstance(v, (int, float))}
    result = _eval(tree, _Budget(MAX_STEPS), env)

    # Post-condition: refuse non-finite and oversized results explicitly
    if isinstance(result, float) and not math.isfinite(result):
        raise ExprRejected("NON_FINITE_RESULT", "")
    if isinstance(result, int) and result.bit_length() > MAX_BITS:
        raise ExprRejected("RESULT_TOO_LARGE", "")
    return result
```

**Hard time bound** (the only real defence against `2 ^ 2 ^ 2 ^ 2 ^ 2`-class inputs, since a step budget does not bound `int` arithmetic cost):

```python
import multiprocessing as mp

def _worker(expr, variables, q):
    try:
        q.put(("ok", safe_evaluate(expr, variables)))
    except ExprRejected as e:
        q.put(("rejected", e.code))

def evaluate_isolated(expr, variables=None, timeout=0.25):
    q = mp.Queue()
    p = mp.Process(target=_worker, args=(expr, variables, q))
    p.start()
    try:
        status, payload = q.get(timeout=timeout)
    except Exception:
        return ("rejected", "TIMEOUT")
    finally:
        p.join(0)
        if p.is_alive():
            p.terminate(); p.kill()
    return (status, payload)
```

